/* ============================================
   WellSource — Health & Wellness Blog
   Design System & Styles
   ============================================ */

/* CSS Custom Properties */
:root {
  --color-primary: #02838D;
  --color-primary-dark: #026970;
  --color-primary-light: #E0F2F1;
  --color-accent: #E07A5F;
  --color-accent-hover: #C96A50;
  --color-text: #231F20;
  --color-text-secondary: #5C5A5B;
  --color-text-muted: #8A8889;
  --color-bg: #FFFFFF;
  --color-bg-warm: #FAFAF8;
  --color-bg-cool: #F5F7F6;
  --color-border: #E8E6E3;
  --color-border-light: #F0EEEB;
  --color-success: #2E7D32;
  --color-warning: #F57C00;

  --font-heading: 'DM Sans', 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px rgba(35, 31, 32, 0.04);
  --shadow-md: 0 4px 12px rgba(35, 31, 32, 0.06);
  --shadow-lg: 0 8px 24px rgba(35, 31, 32, 0.08);
  --shadow-card: 0 2px 8px rgba(35, 31, 32, 0.05);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  --container-max: 1200px;
  --container-padding: 24px;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg);
}

a {
  color: var(--color-primary);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--color-primary-dark);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* Container */
.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--container-padding);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  font-size: 15px;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-accent);
  color: #fff;
  border: 2px solid var(--color-accent);
}

.btn-primary:hover {
  background: var(--color-accent-hover);
  border-color: var(--color-accent-hover);
  color: #fff;
}

.btn-outline {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}

.btn-outline:hover {
  background: var(--color-primary);
  color: #fff;
}

.btn-small {
  padding: 8px 16px;
  font-size: 14px;
}

/* ============================================
   HEADER
   ============================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
}

.header-top {
  padding: 14px 0;
}

.header-top-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--color-text);
  font-family: var(--font-heading);
  font-size: 22px;
  font-weight: 700;
  flex-shrink: 0;
}

.logo:hover {
  color: var(--color-text);
}

.logo-text {
  letter-spacing: -0.5px;
}

/* Main Navigation */
.main-nav {
  flex: 1;
}

.nav-list {
  display: flex;
  align-items: center;
  gap: 4px;
}

.nav-item {
  position: relative;
}

.nav-link {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  font-size: 15px;
  font-weight: 500;
  color: var(--color-text);
  border-radius: var(--radius-sm);
  transition: background var(--transition-fast), color var(--transition-fast);
}

.nav-link:hover,
.nav-link[aria-expanded="true"] {
  background: var(--color-primary-light);
  color: var(--color-primary);
}

.nav-link .chevron {
  transition: transform var(--transition-fast);
}

.nav-link[aria-expanded="true"] .chevron {
  transform: rotate(180deg);
}

/* Mega Dropdown */
.mega-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  min-width: 520px;
  max-width: 720px;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  padding: 20px 0;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition-base);
  z-index: 1001;
}

.mega-dropdown.active {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px 24px;
}

.mega-link {
  display: block;
  padding: 8px 12px;
  font-size: 14px;
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.mega-link:hover {
  background: var(--color-primary-light);
  color: var(--color-primary);
}

/* Header Actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-shrink: 0;
}

.header-action {
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
}

.header-action:hover {
  color: var(--color-primary);
}

/* Mobile Menu Toggle */
.mobile-menu-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
}

.mobile-menu-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-text);
  border-radius: 2px;
  transition: all var(--transition-fast);
}

/* ============================================
   CREDIBILITY TICKER
   ============================================ */
.credibility-bar {
  background: var(--color-primary);
  color: #fff;
  padding: 10px 0;
  overflow: hidden;
}

.ticker-wrap {
  overflow: hidden;
  white-space: nowrap;
}

.ticker-track {
  display: inline-flex;
  gap: 48px;
  animation: ticker-scroll 24s linear infinite;
}

.ticker-item {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
}

.ticker-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  background: rgba(255,255,255,0.6);
  border-radius: 50%;
  flex-shrink: 0;
}

@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ============================================
   HERO SECTION
   ============================================ */
.hero {
  padding: 48px 0 40px;
  background: var(--color-bg-warm);
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 48px;
  align-items: start;
}

.hero-main {
  padding-top: 8px;
}

.hero-category {
  display: inline-block;
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--color-primary);
  margin-bottom: 16px;
}

.hero-title {
  font-family: var(--font-heading);
  font-size: 42px;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.8px;
  margin-bottom: 16px;
  color: var(--color-text);
}

.hero-subtitle {
  font-size: 18px;
  line-height: 1.6;
  color: var(--color-text-secondary);
  margin-bottom: 24px;
  max-width: 540px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 10px 18px;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
}

/* Trending Sidebar */
.trending-sidebar {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 24px;
}

.trending-heading {
  font-family: var(--font-heading);
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 20px;
  color: var(--color-text);
}

.trending-list {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.trending-item {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.trending-tag {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  padding: 3px 8px;
  border-radius: var(--radius-sm);
  width: fit-content;
}

.tag-heart { background: #FFEBEE; color: #C62828; }
.tag-wellness { background: #E0F2F1; color: #00695C; }
.tag-lifestyle { background: #E3F2FD; color: #1565C0; }
.tag-products { background: #FFF3E0; color: #E65100; }

.trending-link {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.4;
  color: var(--color-text);
}

.trending-link:hover {
  color: var(--color-primary);
}

/* ============================================
   NEWSLETTER CTA
   ============================================ */
.newsletter-cta {
  padding: 48px 0;
  background: var(--color-bg-cool);
}

.newsletter-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 40px 48px;
}

.newsletter-content {
  flex: 1;
}

.newsletter-title {
  font-family: var(--font-heading);
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.4px;
  margin-bottom: 8px;
}

.newsletter-body {
  font-size: 16px;
  color: var(--color-text-secondary);
}

.newsletter-form {
  flex-shrink: 0;
  min-width: 380px;
}

.newsletter-input-wrap {
  display: flex;
  gap: 8px;
}

.newsletter-input,
.footer-input {
  flex: 1;
  padding: 12px 16px;
  font-size: 15px;
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  outline: none;
  transition: border-color var(--transition-fast);
}

.newsletter-input:focus,
.footer-input:focus {
  border-color: var(--color-primary);
}

.newsletter-privacy {
  font-size: 12px;
  color: var(--color-text-muted);
  margin-top: 10px;
}

/* ============================================
   HEALTH TOPICS CAROUSEL
   ============================================ */
.health-topics {
  padding: 48px 0;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 28px;
}

.section-title {
  font-family: var(--font-heading);
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.3px;
}

.view-all {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-primary);
}

.view-all:hover {
  text-decoration: underline;
}

.carousel-wrap {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
}

.carousel-scroll {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  padding: 8px 4px;
  margin: -8px -4px;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.carousel-scroll::-webkit-scrollbar {
  display: none;
}

.carousel-arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 50%;
  color: var(--color-text);
  flex-shrink: 0;
  transition: all var(--transition-fast);
  z-index: 2;
}

.carousel-arrow:hover {
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: #fff;
}

.topic-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  text-align: center;
  flex-shrink: 0;
  scroll-snap-align: start;
}

.topic-image {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.topic-card:hover .topic-image {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.topic-label {
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text);
  max-width: 120px;
}

/* ============================================
   HEALTH TOOLS
   ============================================ */
.health-tools {
  padding: 48px 0;
  background: var(--color-bg-warm);
}

.tools-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.tools-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 32px;
}

.tools-card-header {
  margin-bottom: 12px;
}

.tools-card-title {
  font-family: var(--font-heading);
  font-size: 20px;
  font-weight: 700;
}

.tools-card-desc {
  font-size: 15px;
  color: var(--color-text-secondary);
  margin-top: 2px;
}

.tools-card-body {
  font-size: 15px;
  color: var(--color-text-secondary);
  line-height: 1.6;
  margin-bottom: 16px;
}

.tools-cta {
  margin-bottom: 24px;
}

.tools-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.tool-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.tool-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  background: var(--color-primary-light);
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.tool-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tool-info strong {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text);
}

.tool-info span {
  font-size: 13px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

.tool-item-large {
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  background: var(--color-bg-cool);
  border-radius: var(--radius-md);
}

.tool-item-large .tool-info {
  flex: 1;
}

.tool-link {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-primary);
  white-space: nowrap;
  margin-left: 12px;
}

.tool-link:hover {
  text-decoration: underline;
}

/* ============================================
   RECOMMENDED READS (TABS)
   ============================================ */
.recommended-reads {
  padding: 48px 0;
}

.tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 28px;
  flex-wrap: wrap;
  border-bottom: 2px solid var(--color-border-light);
  padding-bottom: 0;
}

.tab-btn {
  padding: 10px 18px;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--color-primary);
  background: var(--color-primary-light);
}

.tab-btn.active {
  color: var(--color-primary);
  border-bottom-color: var(--color-primary);
  background: var(--color-primary-light);
}

.tab-panel {
  display: none;
}

.tab-panel.active {
  display: block;
  animation: fadeIn 300ms ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Article Grid */
.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.article-card {
  display: flex;
  flex-direction: column;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}

.article-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.article-image {
  height: 160px;
  width: 100%;
}

.article-content {
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.article-category {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--color-primary);
}

.article-title {
  font-family: var(--font-heading);
  font-size: 16px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--color-text);
}

/* ============================================
   TRUST SECTION
   ============================================ */
.trust-section {
  padding: 56px 0;
  background: var(--color-bg-cool);
}

.trust-title {
  text-align: center;
  margin-bottom: 40px;
}

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.trust-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 28px;
  text-align: center;
  transition: box-shadow var(--transition-base);
}

.trust-card:hover {
  box-shadow: var(--shadow-md);
}

.trust-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  background: var(--color-primary-light);
  border-radius: var(--radius-full);
  margin-bottom: 16px;
}

.trust-card-title {
  font-family: var(--font-heading);
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 8px;
}

.trust-card-body {
  font-size: 14px;
  line-height: 1.6;
  color: var(--color-text-secondary);
}

/* ============================================
   FEATURED PROGRAMS
   ============================================ */
.featured-programs {
  padding: 48px 0;
}

.programs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.program-card {
  display: block;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}

.program-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.program-image {
  height: 140px;
  width: 100%;
}

.program-title {
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 600;
  line-height: 1.4;
  padding: 16px;
  color: var(--color-text);
}

/* ============================================
   LATEST VIDEOS
   ============================================ */
.latest-videos {
  padding: 48px 0 64px;
  background: var(--color-bg-warm);
}

.videos-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.video-card {
  display: block;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}

.video-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.video-thumbnail {
  position: relative;
  height: 160px;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.play-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  background: rgba(255,255,255,0.95);
  border-radius: 50%;
  color: var(--color-primary);
  box-shadow: var(--shadow-md);
  transition: transform var(--transition-base), background var(--transition-fast);
}

.video-card:hover .play-btn {
  transform: scale(1.08);
  background: #fff;
}

.video-title {
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 600;
  line-height: 1.4;
  padding: 16px;
  color: var(--color-text);
}

/* ============================================
   FOOTER
   ============================================ */
.site-footer {
  background: var(--color-text);
  color: #fff;
  padding: 48px 0 32px;
}

.footer-newsletter {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  padding-bottom: 32px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  margin-bottom: 32px;
}

.footer-newsletter-text {
  font-size: 16px;
  line-height: 1.5;
  max-width: 520px;
  color: rgba(255,255,255,0.85);
}

.footer-form {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}

.footer-input {
  width: 280px;
  background: rgba(255,255,255,0.1);
  border-color: rgba(255,255,255,0.2);
  color: #fff;
}

.footer-input::placeholder {
